import{z as s,x as A,o as t,c as d,q as l,j as o,D as E,d as i,s as n,S as r,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"不对称信息与流动性理论","description":"","frontmatter":{"title":"不对称信息与流动性理论","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/asymmetric-info-liquidity.md","filePath":"econ/asymmetric-info-liquidity.md","lastUpdated":1791413859000}'),m={name:"econ/asymmetric-info-liquidity.md"};function p(D,a,c,h,u,f){const B=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="不对称信息与流动性理论" tabindex="-1">不对称信息与流动性理论 <a class="header-anchor" href="#不对称信息与流动性理论" aria-label="Permalink to &quot;不对称信息与流动性理论&quot;">​</a></h1><div class="epigraph"><p>买卖价差可以是对知情单的保险费：无需存货，无需非理性，只要对手知道得比你多。</p><footer>—— Glosten and Milgrom, Bid, Ask and Transaction Prices in a Specialist Market with Heterogeneously Informed Traders, Journal of Financial Economics, 1985</footer></div><p><a href="/econ/kyle-in-equilibrium">上一课</a>用批量冲击 \\(\\lambda\\) 度量战略不利选择。本课缺口换成<strong>序贯报价</strong>：买价与卖价本身就是条件期望，价差是理论对象，不是簿上的两档挂单。不重做 Kyle 的线性批量，不分解已实现价差的实证成分。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Bagehot（Treynor）已经口头说过：做市商对知情者亏损、对未知情者盈利，价差必须覆盖前者。Glosten 与 Milgrom（1985）把它写成贝叶斯：每来一笔买（卖），做市端把 \\(\\theta\\) 的后验往上（下）移；报价等于成交后的条件期望，否则被知情者自由选取。于是 ask 高于双向成交前的期望，bid 低于它，价差严格为正——即使存货成本为零、即使风险中性。</p><p>缺口是：流动性成本可以完全来自信息不对称。Hellwig 的 \\(z\\) 降低揭示；这里没有 \\(z\\) 也可以有价差，因为方向本身是信号。Kyle 的 \\(\\lambda\\) 是斜率；这里是两点报价。三者同一家族：残差信息租金，不同的交易协议抽象。协议的具体状态机仍不在本栏。</p><p><span class="marginnote">「不利选择」翻译成日常话就是：当交易对手可能比你先知道消息时，愿意主动找你成交的那批单子，恰恰是对你最不利的那批——和保险公司发现「最想投保的人往往风险最高」是同一个机制。</span></p><p><span class="marginnote">Glosten and Milgrom, <em>JFE</em> 14, 1985。风险中性、竞争型做市，把存货与市场力关掉，只留不利选择。Copeland–Galai 更早用期权语言写过类似保险费。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两报价：\\(a=\\mathrm{E}[\\theta\\mid\\text{买}]\\)，\\(b=\\mathrm{E}[\\theta\\mid\\text{卖}]\\)。未知情者以外生动机买或卖，知情者只在有利一侧出现。价差 \\(a-b\\) 随知情者比例、信号精度升，随未知情流量降。交易发生后公共后验更新，下一轮价差可以变——信息被「做进」报价，不必等到清算。</p><p><span class="marginnote">代入一个数：设真值 \\(\\theta\\) 是 50 或 70，各一半概率，无条件期望为 60。知情者只在 \\(\\theta=70\\) 时才买。若到达的买单里知情者占一半，则 ask \\(=0.5\\times 70+0.5\\times 60=65\\)，比无条件期望高 5——这 5 就是买单一侧要付的保险费，卖价同理再抬一半。</span></p><p>与 <a href="/econ/stochastic-discount-factor">随机折现因子</a> 的接缝：这里的 \\(a,b\\) 还不是 \\(p=\\mathrm{E}[m x]\\) 里那个单一 \\(p\\)。不利选择制造的是买卖两个条件期望，线性定价核面对的是可交易方向被分成两张票。本课不把价差写进 \\(m\\)；后课接口才问资产定价该不该给流动性一个状态变量。</p>',12)),(t(),o(r,null,{default:E(()=>[n(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUY%5B%22%E4%B9%B0%E5%8D%95%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20POST%5B%22%E5%90%8E%E9%AA%8C%E4%B8%8A%E7%A7%BB%22%5D%0A%20%20POST%20--%3E%20ASK%5B%22ask%20%3D%20E%5B%CE%B8%7C%E4%B9%B0%5D%22%5D%0A%20%20SELL%5B%22%E5%8D%96%E5%8D%95%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20BID%5B%22bid%20%3D%20E%5B%CE%B8%7C%E5%8D%96%5D%22%5D%0A%20%20ASK%20--%3E%20SPR%5B%22%E4%BB%B7%E5%B7%AE%20%3D%20%E4%B8%8D%E5%88%A9%E9%80%89%E6%8B%A9%E4%BF%9D%E9%99%A9%22%5D%0A%20%20BID%20--%3E%20SPR%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"不要把 \\(a,b\\) 画成限价簿的最佳买卖。本课甚至没有时间优先：每期一个专营商报出两点，成交即更新。簿的几何会把同一不利选择摊到多档与队列，那是换栏之后的事。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是反向选择。愿意在 ask 上买的人群里，知情者比例更高；做市端必须把 ask 定在「被买走之后」的价值上，否则期望亏损。价差因此是配置成本：未知情的流动性需求被征税，知情租金从价差里支付。社会若需要那部分未知情交易（配置、对冲），税是真实的；它不是摩擦的别名，是信息约束的影子价格。",-1)),(t(),o(r,null,{default:E(()=>[n(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B9%B0%E5%8D%95%E4%BA%BA%E7%BE%A4%E9%87%8C%E9%83%BD%E6%9C%89%E8%B0%81%EF%BC%9F%22%5D%20--%3E%20U%5B%22%E6%9C%AA%E7%9F%A5%E6%83%85%E8%80%85%EF%BC%9A%E4%B8%BA%E9%85%8D%E7%BD%AE%E6%88%96%E5%AF%B9%E5%86%B2%E4%B9%B0%E5%85%A5%22%5D%0A%20%20Q%20--%3E%20I%5B%22%E7%9F%A5%E6%83%85%E8%80%85%EF%BC%9A%E4%BB%85%E5%9C%A8%E7%9C%9F%E5%80%BC%E9%AB%98%E4%BA%8E%20ask%20%E6%97%B6%E4%B9%B0%22%5D%0A%20%20U%20--%3E%20MIX%5B%22%E4%B9%B0%E5%8D%95%E8%A2%AB%E7%9F%A5%E6%83%85%E8%80%85%E3%80%8E%E6%B1%A1%E6%9F%93%E3%80%8F%22%5D%0A%20%20I%20--%3E%20MIX%0A%20%20MIX%20--%3E%20RAISE%5B%22ask%20%E6%8A%AC%E5%88%B0%E6%88%90%E4%BA%A4%E5%90%8E%E7%9A%84%E6%9D%A1%E4%BB%B6%E6%9C%9F%E6%9C%9B%22%5D%0A%20%20RAISE%20--%3E%20TAX%5B%22%E6%9C%AA%E7%9F%A5%E6%83%85%E8%80%85%E6%8C%89%E4%BB%B7%E5%B7%AE%E4%BB%98%E4%BF%9D%E9%99%A9%E8%B4%B9%22%5D%0A%20%20TAX%20--%3E%20EXIT%5B%22%E4%BB%98%E8%B4%B9%E5%A4%AA%E8%B4%B5%EF%BC%8C%E9%83%A8%E5%88%86%E6%9C%AA%E7%9F%A5%E6%83%85%E6%B5%81%E9%87%8F%E7%A6%BB%E5%9C%BA%22%5D%0A%20%20EXIT%20--%3E%20LOOP%5B%22%E6%B5%81%E9%87%8F%E9%99%8D%20%E2%86%92%20%E7%9F%A5%E6%83%85%E5%8D%A0%E6%AF%94%E6%9B%B4%E5%8D%87%20%E2%86%92%20%E4%BB%B7%E5%B7%AE%E6%9B%B4%E5%AE%BD%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">常见误区：把价差当成做市商的「利润」。在竞争性报价下，买卖价差恰好被对知情者成交的期望亏损吃掉，做市商期望利润为零——它是保费的价格，不是租金；垄断做市才会另外加一块市场力租金。</span></p><p>GS 说完全揭示不能与采集共存；本课说即便信号已经存在，只要它还没被价格完全吸收，交易就要付保险费。两条在时间上衔接：采集决定有多少知情者，序贯报价决定他们如何把信息做进 \\(p\\)。</p><p><span class="marginnote">存货模型（Stoll, Ho–Stoll）给出另一条价差：风险厌恶做市商为库存要补偿。本课关掉它，是为了单独看见信息。两条可以加，但加总不是本课任务，更不是实证分解。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在这里写 Roll 估计、价差分解回归、PIN。那些是量化栏对这条理论的测量。也不要把「流动性」升级成偏好参数——后文便利收益会给安全资产一个非信息的流动性溢价，对象不同。</p><p>下一课问知情者自己会不会把信号<strong>说出来</strong>（披露），而不是只通过交易泄漏。价差是泄漏的价格；披露是主动的公共信号。</p><p>后课默认：不对称信息足以产生价差与价格冲击，无需存货或非理性。本栏的 \\(a,b,\\lambda\\) 是条件期望对象，不是盘口数据。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Glosten–Milgrom：买卖报价是方向条件期望，价差是不利选择保险。</li><li>与 Kyle 的 \\(\\lambda\\)、Hellwig 的 \\(z\\) 同一家族，协议抽象不同。</li><li>实证分解与簿几何换栏；本课不写。</li><li>出处：Glosten and Milgrom, <em>JFE</em> 1985；对照 Kyle 1985。</li></ul>',9))])}const T=s(m,[["render",p]]);export{b as __pageData,T as default};
